from browser_support import ROOT,launch
from story_browser_server import story_base_url
OUT=ROOT/'review/stage24';BASE=story_base_url();rows=[];errors=[]
SNAP='''expression=>{const r=eval(expression),b=r.engine.b;return {stage:b.honroStage,terrain:b.terrain.map(t=>({id:t.id,vertices:t.vertices,oneWay:t.oneWay,element:t.honroElementId})),markers:b.honroMarkers.map(m=>({id:m.id,x:m.x,y:m.y}))};}'''
with sync_playwright()as p:
 browser=launch(p)
 for mobile in [False,True]:
  tag='mobile'if mobile else'desktop';ctx=browser.new_context(viewport={'width':390,'height':844}if mobile else{'width':1440,'height':900},is_mobile=mobile,has_touch=mobile);page=ctx.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto(BASE+'/HONRO_WORKSHOP.html');page.wait_for_function('window.HonroWorkshopAPI?.getRuntime()?.scene');page.evaluate("HonroWorkshopAPI.selectStage('stage-24');HonroWorkshopAPI.setCamera({x:2200,y:2300,scale:.55});HonroWorkshopAPI.setOverlay(false)");page.wait_for_timeout(200);stage=page.evaluate(SNAP,'HonroWorkshopAPI.getRuntime()');saved=page.evaluate('HonroWorkshopAPI.exportProject()');roofs=[t for t in stage['terrain']if t.get('element')in['outer-servant-wing','ancestral-family-hall','garden-study','family-ancestral-shrine','ground-record-entry']];assert len(roofs)==5 and all(t['oneWay']for t in roofs);page.screenshot(path=str(OUT/f'workshop-{tag}-stage-view.png'))
  page.click('[data-tab="play"]');page.wait_for_function('HonroWorkshopAPI.getPlayApp()?.engine');frame=page.frames[1];frame.evaluate('()=>{const a=HonroApp;while(a.dialogue)HonroStory.finish(a);a.turnNotice=null;}');played=frame.evaluate(SNAP,'HonroApp');assert stage==played,'Stage View/Playtest exact terrain and markers'
  frame.evaluate("""()=>{const a=HonroApp,e=a.engine,b=e.b,u=e.active,t=b.terrain.find(t=>t.honroElementId==='ancestral-family-hall');Object.assign(u,{x:2600,y:HONRO_CORE.topAt(t,2600),vx:0,vy:0,airborne:false,jumping:false});a.actorBoundary=b.active;a.turnNotice=null;a.lastTurnNotice=`${b.round}:player`;document.getElementById('turn-banner').hidden=true;a.updateHUD(true);Object.assign(a.scene,{x:2600,y:2230,scale:.7,manual:true,storyTween:null,goalFocus:null,focusUntil:0});}""");page.wait_for_timeout(150);page.screenshot(path=str(OUT/f'workshop-{tag}-playtest-roof.png'));frame.locator('#drop').click();frame.wait_for_function("HonroApp.engine.grounded(HonroApp.engine.active)&&HonroApp.engine.contactSurface(HonroApp.engine.active.x,HonroApp.engine.active.y-2,HonroApp.engine.active.y+2)?.t.id==='family24-hall-east-step'");page.wait_for_timeout(300);frame.locator('#drop').click();frame.wait_for_function("HonroApp.engine.grounded(HonroApp.engine.active)&&HonroApp.engine.contactSurface(HonroApp.engine.active.x,HonroApp.engine.active.y-2,HonroApp.engine.active.y+2)?.t.id==='a3-foundation'");page.click('#stopPlay');assert page.evaluate('HonroWorkshopAPI.exportProject()')==saved;rows.append({'device':tag,'fiveRoofsOneWay':True,'stageViewPlaytestExactTerrainMarkers':True,'actualDropButtonsRoofEaveGround':True,'stopRestoresProject':True,'roofIds':[r['id']for r in roofs]});ctx.close()
 browser.close()
assert not errors,errors
(OUT/'workshop-browser.json').write_text(json.dumps({'scope':__doc__,'passed':True,'rows':rows,'errors':errors,'html':{f:{'bytes':(ROOT/f).stat().st_size,'sha256':hashlib.sha256((ROOT/f).read_bytes()).hexdigest()}for f in ['HONRO.html','HONRO_WORKSHOP.html']}},ensure_ascii=False,indent=2));print('PASS desktop/mobile StageView/Playtest parity, 5 one-way roofs, actual drop button twice, Stop preservation')
